CGSOLV = λ(B, X, TOL, MAXIT).
    let Q = AMUL(X)
    let R = B - Q
    let Z = PCOND(R)
    let P = DCOPY(Z)
    let RHO = DDOT(R, Z)
    let BNRM = DNRM2(B)
    let ITER = 0
    let RNORM = DNRM2(R)
    while_loop  cond: not (RNORM <= TOL * BNRM) and not (ITER >= MAXIT)
        let ITER = ITER + 1
        let Q = AMUL(P)
        let ALPHA = RHO / DDOT(P, Q)
        let X = DAXPY(ALPHA, P, X)
        let R = DAXPY(-ALPHA, Q, R)
        let Z = PCOND(R)
        let RHONEW = DDOT(R, Z)
        let BETA = RHONEW / RHO
        let RHO = RHONEW
        let P = XPAY(Z, BETA, P)
        let RNORM = DNRM2(R)
    in  {X = X, W = [R ++ Z ++ P ++ Q], ITER = ITER, RNORM = RNORM}

