PCG = λ(b, x, tol, maxit).
    let q = A(x)
    let r = b - q
    let z = Minv(r)
    let p = copy(z)
    let rho = dot(r, z)
    let bn = nrm(b)
    let k = 0
    let rn = nrm(r)
    while_loop  cond: not (rn <= tol * bn) and not (k >= maxit)
        let k = k + 1
        let q = A(p)
        let alpha = rho / dot(p, q)
        let x = axpy(alpha, p, x)
        let r = axpy(-alpha, q, r)
        let z = Minv(r)
        let rho1 = dot(r, z)
        let beta = rho1 / rho
        let rho = rho1
        let p = xpay(z, beta, p)
        let rn = nrm(r)
    in  {X = x, ITER = k, RNORM = rn}
